options.helpers:
context.handlebars.registerHelper("CtName", (id) => {
  if (id === 'ct1') return 'CT-1';
  if (id === 'ct2') return 'CT-2';
  if (id === 'ct3') return 'CT-3';
  return id;
})

context.handlebars.registerHelper("CtByPriority", (towers, priority) => {
  const ct = towers.find(t => t.priority === priority);
  return ct?.deviceId ?? '--';
})

context.handlebars.registerHelper("RunningCT", (towers) => {
  return towers.filter(t => t.state === 2).length; // 2 = running
});

context.handlebars.registerHelper('numberFormat', function (value, options) {
  if (value == null) return '---';

  // Helper parameters
  var dl = options.hash['decimalLength'] || 0;
  var ts = options.hash['thousandsSep'] || ',';
  var ds = options.hash['decimalSep'] || '.';

  // Parse to float
  var value = parseFloat(value);

  // The regex
  var re = '\\d(?=(\\d{3})+' + (dl > 0 ? '\\D' : '$') + ')';

  // Formats the number with the decimals
  var num = value.toFixed(Math.max(0, ~~dl));

  // Returns the formatted number
  return (ds ? num.replace('.', ds) : num).replace(new RegExp(re, 'g'), '$&' + ts);
});

context.handlebars.registerHelper('setpointSummary', function (value, setpoint) {
  const gap = value - setpoint;
  if (gap < 0) {
    return `${Math.abs(gap).toFixed(1)} °C below setpoint`;
  }

  if (gap > 0) {
    return `${gap.toFixed(1)} °C above setpoint`;
  }

  return `same as setpoint`
})

context.handlebars.registerHelper('setpointStatus', function (value, setpoint) {
  const gap = value - setpoint;
  const threshold = Number(context.grafana.replaceVariables('${setpointThreshold}'));
  return gap <= threshold ? 'good' : 'bad';
});

context.handlebars.registerHelper('runningFans', function (count) {
  if (count === 0) return `No fan running`;
  if (count === 1) return `1 fan running`;
  return `${count} fans running`;

})

// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
  if (theme) return theme.isDark ? 'dark' : 'light';
  return document.body.classList.contains('theme-light') ? 'light' : 'dark';
});

