context.handlebars.registerHelper("defaultRow", (range, defaultTarget, setpoint) => {
  const last = range[range.length - 1];
  const isActive = defaultTarget == setpoint;
  return `
  <tr>
    <td>&gt;= ${last.max} °C</td>
    <td>${defaultTarget} °C</td>
    <td ${isActive ? '' : 'class="ct-setpoint-muted"'}>${isActive ? '<span class="ct-setpoint-status">ACTIVE</span>' : '-'}</td>
  </tr>`
})

